--   2. Stop the Checkride app (this hook replaces its callbacks).
--   3. Restart DCS, then load any mission (needed for airdrome data).
--   4. Output is written to:
--        <Saved Games>\DCS\checkride-enrichment.json
--   5. Back on the host machine, run:
--        node dev/tools/buildReferenceData.js process
--   6. Remove this hook file and restart DCS to restore normal operation.
--
-- Unit/weapon enrichment runs at simulation start (no mission needed).
-- Airdrome enumeration runs on mission load.  If you only need units/weapons,
-- the partial output written at sim-start is sufficient.

local lfs = require('lfs')
local log = require('log')

local function enrichLog(msg)
    log.write('CheckrideEnricher', log.INFO, tostring(msg))
end

-- ====================================================================
-- JSON encoder (mirrors DCS-CheckrideMission.lua style)
-- ====================================================================
local function jsonEscape(str)
    str = tostring(str)
    str = str:gsub('\\', '\\\\')
    str = str:gsub('"',  '\\"')
    str = str:gsub('\n', '\\n')
    str = str:gsub('\r', '\\r')
    str = str:gsub('\t', '\\t')
    return str
end

local function isSeqTable(t)
    if type(t) ~= 'table' then return false end
    local n = 0
    for k in pairs(t) do
        if type(k) ~= 'number' then return false end
        n = n + 1
    end
    for i = 1, n do if t[i] == nil then return false end end
    return true
end

local function encodeJson(val, depth)
    depth = depth or 0
    if depth > 20 then return '"<depth_limit>"' end
    local t = type(val)
    if t == 'nil'     then return 'null' end
    if t == 'boolean' then return tostring(val) end
    if t == 'number'  then
        if val ~= val or val >= math.huge or val <= -math.huge then return 'null' end
        return tostring(val)
    end
    if t == 'string' then return '"' .. jsonEscape(val) .. '"' end
    if t == 'table' then
        if isSeqTable(val) then
            local parts = {}
            for i, v in ipairs(val) do parts[i] = encodeJson(v, depth + 1) end
            return '[' .. table.concat(parts, ',') .. ']'
        end
        local parts = {}
        for k, v in pairs(val) do
            if type(k) == 'string' then
                table.insert(parts, '"' .. jsonEscape(k) .. '":' .. encodeJson(v, depth + 1))
            end
        end
        return '{' .. table.concat(parts, ',') .. '}'
    end
    return 'null'
end

